// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(uint56 changeFeeArg, uint16 feeRateArg) public {
        vm.assume(uint256(changeFeeArg) != uint256(feeRateArg));
        vm.assume(feeRateArg <= 5_000);

        c.initialize(
            address(0),
            address(0),
            0,
            0,
            changeFeeArg,
            feeRateArg,
            bytes32(0),
            false,
            false
        );

        assertTrue(uint256(c.changeFee()) == uint256(changeFeeArg));
    }
}
